<section data-name="Quote" data-node-id="857:15238" data-role="quote" data-tone="white"><div data-part="artwork" aria-hidden="true"><img src="{base}/media/c637e0d8e458864a395d.svg" alt="" loading="lazy"></div><div data-part="copy"><p data-node-id="I857:15238;750:751" data-part="eyebrow">people experience</p>
<p data-part="paragraph" class="display-prose"><span class="sr-only">“The Vessyl is a sanctuary on the edge of the Arenal volcano, where nature, sound, and sensory experience are composed with intention.</span><span class="type-visual" aria-hidden="true"><svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 87.891 46.4" style="width:2.1972750000000003em"><use href="{base}/typography/193fad656a272a53d350.svg#word-0" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 120.118 46.4" style="width:3.00295em"><use href="{base}/typography/193fad656a272a53d350.svg#word-1" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 30.84 46.4" style="width:0.771em"><use href="{base}/typography/193fad656a272a53d350.svg#word-2" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 20.997 46.4" style="width:0.524925em"><use href="{base}/typography/193fad656a272a53d350.svg#word-3" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 186.485 46.4" style="width:4.6621250000000005em"><use href="{base}/typography/193fad656a272a53d350.svg#word-4" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 49.161 46.4" style="width:1.229025em"><use href="{base}/typography/193fad656a272a53d350.svg#word-5" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 63.204 46.4" style="width:1.5801em"><use href="{base}/typography/193fad656a272a53d350.svg#word-6" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 94.278 46.4" style="width:2.3569500000000003em"><use href="{base}/typography/193fad656a272a53d350.svg#word-7" width="100%" height="100%"><