ht="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 213.399 46.4" style="width:5.334975em"><use href="{base}/typography/193fad656a272a53d350.svg#word-17" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 61.836 46.4" style="width:1.5459em"><use href="{base}/typography/193fad656a272a53d350.svg#word-18" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 203.379 46.4" style="width:5.084474999999999em"><use href="{base}/typography/193fad656a272a53d350.svg#word-19" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 82.442 46.4" style="width:2.06105em"><use href="{base}/typography/193fad656a272a53d350.svg#word-20" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 183.653 46.4" style="width:4.591324999999999em"><use href="{base}/typography/193fad656a272a53d350.svg#word-21" width="100%" height="100%"></use></svg></span></p>
<p data-part="paragraph" class="display-prose"><span class="sr-only">Every space is built to help the nervous system settle and the mind grow still, so that presence returns on its own. It is less a place you visit than a set of conditions, carefully made, for feeling like yourself again.”</span><span class="type-visual" aria-hidden="true"><svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 105.645 46.4" style="width:2.6411249999999997em"><use href="{base}/typography/b1f7600c35645fdcb1a1.svg#word-0" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 111.465 46.4" style="width:2.786625em"><use href="{base}/typography/b1f7600c35645fdcb1a1.svg#word-1" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 30.84 46.4" style="width:0.771em"><use href="{base}/typography/b1f7600c35645fdcb1a1.svg#word-2" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 86.993 46.4" style="width:2.174825em"><use href="{base}/typography/b1f7600c35645fdcb1a1.svg#word-3" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 41.27 46.4" style="width:1.0317500000000002em"><use href="{base}/typography/b1f7600c35645fdcb1a1.svg#word-4" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 83.086 46.4" style="width:2.07715em"><use href="{base}/typography/b1f7600c35645fdcb1a1.svg#word-5" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 63.204 46.4" style="width:1.5801em"><use href="{base}/typography/b1f7600c35645fdcb1a1.svg#word-6" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 153.711 46.4" style="width:3.8427750000000005em"><us